#include <memory>
#include <iostream>

class Tracker {
public:
    int id;
    Tracker(int i) : id(i) { std::cout << "Created " << id << "\n"; }
    ~Tracker() { std::cout << "Deleted " << id << "\n"; }
};

int main() {
    std::auto_ptr<Tracker> ptr1(new Tracker(100));
    std::auto_ptr<Tracker> ptr2(new Tracker(200));

    std::cout << "--- Assignment ---\n";
    ptr2 = ptr1; // Deletes object 200, transfers 100 ownership
    std::cout << "Ptr1 is null: " << (ptr1.get() == nullptr) << "\n";
    // Object 100 deleted when ptr2 goes out of scope
    return 0;
}
